SELECT
  co_ownership_cost - LAG(co_ownership_cost, 1, 0) OVER (ORDER BY id) AS cost_change
FROM co_ownership;

SELECT T1.region, AVG(T1.pollution_level)
FROM air_quality AS T1 JOIN policies AS T2 ON T1.region = T2.region AND T2.policy_type = 'Industrial'
GROUP BY T1.region;

SELECT T1.MineName, T2.JobType, COUNT(T2.EmployeeID)
FROM Mine AS T1 JOIN Employee AS T2 ON T1.MineID = T2.MineID
GROUP BY T1.MineName, T2.JobType;

SELECT type, resolution_method, CAST(SUM(CASE WHEN success = TRUE THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*)
FROM disputes
GROUP BY type, resolution_method;
